// Check if we can satisfy the request within the current block
if (n <= b.size) {
    // Case 1: Same size or shrink - just adjust the block size
    b.size = n;
    return true;
}

// Case 2: Expand in-place if possible
size_t available = max_size - (p - data);
if (p + b.size == data + max_size || // At end of buffer
    (p + b.size < data + max_size && // Not at end, but has enough space after
     available >= n - b.size)) {
    b.size = n;
    return true;
}

// Case 3: Need to allocate-copy-deallocate
char* new_ptr = p;
size_t space_needed = n + alignment - 1;

// Check if we have enough space at current position with alignment
size_t current_offset = p - data;
size_t aligned_offset = (current_offset + alignment - 1) & ~(alignment - 1);
size_t aligned_space = max_size - aligned_offset;

if (aligned_space >= n) {
    // Can fit with proper alignment at current position
    new_ptr = data + aligned_offset;
    if (new_ptr != p) {
        std::memmove(new_ptr, p, b.size);
    }
    p = new_ptr;
    b.size = n;
    return true;
}

// Check if we can fit anywhere in the buffer
size_t remaining = max_size;
char* candidate = data;
while (remaining >= n) {
    size_t offset = candidate - data;
    size_t aligned_off = (offset + alignment - 1) & ~(alignment - 1);
    if (aligned_off + n <= max_size) {
        new_ptr = data + aligned_off;
        if (new_ptr != p) {
            std::memmove(new_ptr, p, b.size);
        }
        p = new_ptr;
        b.size = n;
        return true;
    }
    candidate++;
    remaining--;
}

// Failed to reallocate
return false;

